{
  "name": "@justmpm/ai-tool",
  "version": "6.1.1",
  "description": "Ferramenta de análise de código para projetos TypeScript/JavaScript. Mapa do projeto, impacto de mudanças, Cloud Functions, busca de símbolos e áreas funcionais. Usa Skott + ts-morph internamente.",
  "keywords": [
    "dependency-analysis",
    "impact-analysis",
    "code-analysis",
    "symbol-search",
    "typescript",
    "javascript",
    "skott",
    "ai",
    "claude",
    "opencode"
  ],
  "author": "Koda AI Studio <studio.kodaai@gmail.com>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/anthropic-studio/ai-tool.git"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "ai-tool": "dist/cli.js"
  },
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup src/index.ts src/cli.ts --format esm --dts --clean && tsup --config tsup.worker.config.ts",
    "dev": "tsup src/index.ts src/cli.ts --format esm --dts --watch",
    "prepublishOnly": "npm run build",
    "test": "vitest run",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.25.3",
    "minimatch": "^10.0.1",
    "minisearch": "^7.2.0",
    "parse-git-diff": "^0.0.20",
    "skott": "^0.35.8",
    "stemmer": "^2.0.1",
    "ts-morph": "^27.0.2",
    "zod": "^3.25.76"
  },
  "devDependencies": {
    "@types/node": "^22.15.21",
    "tsup": "^8.5.0",
    "tsx": "^4.19.0",
    "typescript": "^5.8.3",
    "vitest": "^4.1.0"
  },
  "overrides": {
    "effect": "3.20.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}

#!/usr/bin/env node
import {
  describe
} from "./chunk-TH6U4SWS.js";
import {
  VERSION,
  area,
  areaContext,
  areas,
  areasInit,
  changes,
  context,
  find,
  functions,
  impact,
  map,
  suggest
} from "./chunk-E6XYBRXH.js";

// src/cli.ts
import { resolve } from "path";
var HELP = `
ai-tool v${VERSION} - Analise de dependencias e impacto

COMANDOS:
  map                    Resumo do projeto: contagens e areas
  map --full             Mapa completo com lista de arquivos
  impact <arquivo>       Analise de impacto antes de modificar
  suggest <arquivo>      Sugere arquivos para ler antes de modificar
  context <arquivo>      Extrai assinaturas de um arquivo (funcoes, tipos)
  context --area=<nome>  Contexto consolidado de toda uma area
  find <termo>           Busca simbolos no codigo (funcoes, tipos, etc)
  describe <termo>       Busca areas por descricao em linguagem natural

AREAS:
  areas                  Lista todas as areas/dominios do projeto
  areas --missing        Mostra apenas arquivos sem area definida (lista completa)
  areas init             Gera arquivo de configuracao .analyze/areas.config.json
  areas init --force     Sobrescreve configuracao existente
  area <nome>            Mostra arquivos de uma area especifica
  area <nome> --type=hook   Filtra por categoria
  area <nome> --full     Mostra todos os arquivos

BUSCA (find):
  find <termo>           Busca definicao + usos de um simbolo
  find <termo> --type=function|type|const|component|hook|trigger
  find <termo> --area=auth   Busca apenas em uma area
  find <termo> --def     Mostra apenas definicoes
  find <termo> --refs    Mostra apenas referencias/usos

FIREBASE:
  functions              Lista todas as Cloud Functions do projeto
  functions --trigger=onCall   Filtra por tipo de trigger

CHANGES:
  changes                Resumo semantico de mudancas git
  changes --staged       Mudancas no staging area (git add)
  changes --unstaged     Mudancas no working directory
  changes --commit=HEAD~2   Mudancas de um commit especifico (commit^1..commit)
  changes --range=HEAD~2..HEAD   Mudancas acumuladas entre duas refs
  changes --file=src/types/auth.ts  Detalhar um arquivo especifico

  MODOS:
  --mcp                  Inicia servidor MCP para integracao com Claude Desktop

OPCOES:
  --format=text|json     Formato de saida (default: text)
  --cwd=<path>           Diretorio do projeto (default: cwd)
  --no-cache             Ignora cache e forca regeneracao
  --limit=<n>            Limite explicito de sugestoes (apenas suggest)
  --type=<categoria>     Filtra por categoria (area) ou tipo de simbolo (find)
  --full                 Lista completa (map: lista arquivos, area: todos arquivos)
  --area=<nome>          Filtra por area (find, context)
  --missing              Mostra apenas arquivos sem area (areas)
  --def                  Apenas definicoes (find)
  --refs                 Apenas referencias (find)
  --commit=<ref>         Analisa mudancas de um commit especifico (changes)
  --range=<from..to>     Analisa mudancas entre duas refs (changes)
  --help, -h             Mostra esta ajuda
  --version, -v          Mostra versao

CACHE:
  Resultados sao salvos em .analyze/ para acelerar execucoes futuras.
  O cache e invalidado automaticamente quando arquivos mudam.
  Use --no-cache para forcar regeneracao.

EXEMPLOS:
  ai-tool map                      # Resumo compacto
  ai-tool map --full               # Lista completa de arquivos
  ai-tool impact Button
  ai-tool suggest Button
  ai-tool suggest Button --limit=5   # Opcional: limita explicitamente a saida
  ai-tool context Button
  ai-tool context --area=auth      # Contexto de toda a area auth
  ai-tool find useAuth             # Busca definicao e usos
  ai-tool find User --type=type    # Busca apenas tipos
  ai-tool find login --area=auth   # Busca na area auth
  ai-tool describe cache           # Busca areas por descricao
  ai-tool areas
  ai-tool area auth
  ai-tool area auth --type=hook
  ai-tool --mcp

SOBRE:
  Criado por Koda AI Studio (kodaai.app)
  Usa Skott para analise de dependencias.
`;
async function main() {
  const args = process.argv.slice(2);
  const flags = {};
  const positional = [];
  for (const arg of args) {
    if (arg.startsWith("--")) {
      const [key, value] = arg.slice(2).split("=");
      flags[key] = value ?? true;
    } else if (arg.startsWith("-")) {
      const key = arg.slice(1);
      flags[key] = true;
    } else {
      positional.push(arg);
    }
  }
  if (flags.mcp) {
    const { startMcpServer } = await import("./server-X3ZDY3QR.js");
    await startMcpServer();
    return;
  }
  if (flags.help || flags.h || positional.length === 0) {
    console.log(HELP);
    process.exit(0);
  }
  if (flags.version || flags.v) {
    console.log(`ai-tool v${VERSION}`);
    process.exit(0);
  }
  const command = positional[0];
  const target = positional[1];
  const format = flags.format || "text";
  const cwd = flags.cwd ? resolve(flags.cwd) : process.cwd();
  const cache = !flags["no-cache"];
  try {
    let result;
    switch (command) {
      case "map":
        result = await map({ format, cwd, cache, full: !!flags.full });
        break;
      case "impact":
        if (!target) {
          console.error("\u274C Erro: arquivo alvo \xE9 obrigat\xF3rio para o comando impact");
          console.error("   Exemplo: ai-tool impact src/components/Button.tsx");
          console.error("   Exemplo: ai-tool impact Button");
          process.exit(1);
        }
        result = await impact(target, { format, cwd, cache });
        break;
      case "suggest":
        if (!target) {
          console.error("\u274C Erro: arquivo alvo \xE9 obrigat\xF3rio para o comando suggest");
          console.error("   Exemplo: ai-tool suggest src/components/Button.tsx");
          console.error("   Exemplo: ai-tool suggest Button");
          process.exit(1);
        }
        result = await suggest(target, {
          format,
          cwd,
          cache,
          limit: flags.limit ? Number(flags.limit) : void 0
        });
        break;
      case "context":
        if (flags.area) {
          result = await areaContext(flags.area, { format, cwd, cache });
          break;
        }
        if (!target) {
          console.error("\u274C Erro: arquivo alvo \xE9 obrigat\xF3rio para o comando context");
          console.error("   Exemplo: ai-tool context src/components/Button.tsx");
          console.error("   Exemplo: ai-tool context Button");
          console.error("   Exemplo: ai-tool context --area=auth");
          process.exit(1);
        }
        result = await context(target, { format, cwd });
        break;
      case "find":
        if (!target) {
          console.error("\u274C Erro: termo de busca \xE9 obrigat\xF3rio para o comando find");
          console.error("   Exemplo: ai-tool find useAuth");
          console.error("   Exemplo: ai-tool find User --type=type");
          console.error("   Exemplo: ai-tool find login --area=auth");
          process.exit(1);
        }
        result = await find(target, {
          format,
          cwd,
          cache,
          type: flags.type,
          area: flags.area,
          def: !!flags.def,
          refs: !!flags.refs
        });
        break;
      case "areas":
        if (target === "init") {
          result = await areasInit({ cwd, force: !!flags.force });
        } else {
          result = await areas({ format, cwd, missing: !!flags.missing });
        }
        break;
      case "area":
        if (!target) {
          console.error("\u274C Erro: nome da \xE1rea \xE9 obrigat\xF3rio para o comando area");
          console.error("   Exemplo: ai-tool area auth");
          console.error("   Use 'ai-tool areas' para listar \xE1reas dispon\xEDveis");
          process.exit(1);
        }
        result = await area(target, {
          format,
          cwd,
          type: flags.type,
          full: !!flags.full
        });
        break;
      case "functions":
        result = await functions({
          format,
          cwd,
          cache,
          trigger: flags.trigger
        });
        break;
      case "describe":
        if (!target) {
          console.error("\u274C Erro: termo de busca \xE9 obrigat\xF3rio para o comando describe");
          console.error("   Exemplo: ai-tool describe cache");
          console.error("   Exemplo: ai-tool describe login");
          process.exit(1);
        }
        result = await describe(target, { format, cwd });
        break;
      case "changes":
        result = await changes({
          format,
          cwd,
          target: flags.staged ? "staged" : flags.unstaged ? "unstaged" : "all",
          file: flags.file,
          commit: flags.commit,
          range: flags.range
        });
        break;
      default:
        console.error(`\u274C Comando desconhecido: ${command}`);
        console.error("   Use 'ai-tool --help' para ver comandos dispon\xEDveis.");
        process.exit(1);
    }
    console.log(result);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`\u274C Erro: ${message}`);
    process.exit(1);
  }
}
main();
